CREATE TABLE IF NOT EXISTS admin_roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,description VARCHAR(255) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY admin_role_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,permission_key VARCHAR(120) NOT NULL,description VARCHAR(255) NULL,UNIQUE KEY admin_permission_key(permission_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_user_roles (user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80) NULL,entity_id BIGINT UNSIGNED NULL,old_values JSON NULL,new_values JSON NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(1000) NULL,created_at TIMESTAMP NULL,KEY audit_user(user_id,created_at),KEY audit_entity(entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS platform_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(160) NOT NULL,setting_value TEXT NULL,setting_type ENUM('string','boolean','integer','decimal','json') NOT NULL DEFAULT 'string',is_public TINYINT(1) NOT NULL DEFAULT 0,updated_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY platform_setting_key(setting_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
